import itertools
import math

def is_perfect_power(N):
    if N <= 1:
        return (N == 1, 1, 1) # Treat 1 as 1^c, or handle based on constraints. Here, n_S, c must be positive integers.

    # Check for perfect squares (c=2)
    c2 = int(math.isqrt(N))
    if c2 * c2 == N:
        return (True, c2, 2)

    # Check for perfect cubes (c=3)
    c3 = round(N**(1/3))
    if c3**3 == N:
        return (True, c3, 3)

    # Check higher powers up to the maximum possible exponent (log2(N))
    max_c = int(math.log2(N))

    for c in range(4, max_c + 1):
        # Estimate base n_S
        n_S_float = N**(1/c)
        n_S = round(n_S_float)

        # Check integer base
        if n_S > 1 and n_S**c == N:
            return (True, n_S, c)

    return (False, None, None)

solutions = []
N_B_range = range(1, 5)
A_range = range(1, 4)
N_T_range = range(1, 5)
B_range = range(1, 4)

# Iterate over all combinations for B and T bases/exponents
for n_B, a in itertools.product(N_B_range, A_range):
    for n_T, b in itertools.product(N_T_range, B_range):

        # Calculate the value N = n_B^a + n_T^b
        try:
            N = n_B**a + n_T**b
        except OverflowError:
            continue

        # Check if N is a perfect power n_S^c
        is_power, n_S, c = is_perfect_power(N)

        if is_power:
            # We found a valid combination: n_B^a + n_T^b + 1 = n_S^c

            B = n_B**a + 1
            T = n_T**b + 1
            S = N + 1

            # Store the full details
            solutions.append({
                'B': B, 'T': T, 'S': S,
                'n_B': n_B, 'a': a,
                'n_T': n_T, 'b': b,
                'n_S': n_S, 'c': c
            })

# Remove duplicates based on the resulting (B, T, S) triple
unique_solutions = {}
for sol in solutions:
    key = (sol['B'], sol['T'], sol['S'])
    # If a key already exists, we might have multiple ways to generate it. 
    # We only need one representative for the list.
    if key not in unique_solutions:
        unique_solutions[key] = sol

final_list = list(unique_solutions.values())

print(f"Total unique triples found: {len(final_list)}")
print("--- Detailed List ---")

# Print the required format
for i, sol in enumerate(final_list):
    print(f"Triple {i+1}: (B={sol['B']}, T={sol['T']}, S={sol['S']})")
    print(f"  B parameters: (n_B={sol['n_B']}, a={sol['a']})")
    print(f"  T parameters: (n_T={sol['n_T']}, b={sol['b']})")
    print(f"  S parameters: (n_S={sol['n_S']}, c={sol['c']})")
    print("-" * 20)
